from pathlib import Path
import json
for p in ['QA/release/gate4_static.json','QA/release/gate4_runtime.json','QA/release/gate4.json','QA/release/qualification.json']:
    d=json.loads(Path(p).read_text())
    print('\\n'+p, 'status=',d.get('status'),'candidate_head=',d.get('candidate_head'))
    print('keys=',sorted(d))
    for key in ('checks','tests','assets','provider_transitions','blocked_network','external_provider','delivery','package'):
        if key in d:
            v=d[key]
            if isinstance(v,dict): print(key+' keys=',sorted(v))
            elif isinstance(v,list): print(key+' len=',len(v),'sample=',v[:2])
            else: print(key+'=',v)
